def transform(grid):
    # Remove single-cell noise objects that share the template color.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    from collections import Counter
    counts=Counter(x for row in grid for x in row)
    bg=max(counts,key=counts.get)
    # Target the most common foreground color; change singleton components in top half to bg.
    fg=max((c for c in counts if c!=bg),key=lambda c:counts[c])
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=fg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==fg and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
